import unittest
from delivery import label, dispatch
class DeliveryTests(unittest.TestCase):
    def test_label(self): self.assertEqual(label(" Ada "), "Ada")
    def test_refund(self): self.assertEqual(dispatch("refund", " Ada "), "Ada")
    def test_invalid_refund(self):
        with self.assertRaises(ValueError): dispatch("refund", 7)
